from marshmallow import Schema, fields, validate, validates_schema, ValidationError


class RegisterSchema(Schema):
    username = fields.Str(
        required=True,
        validate=[
            validate.Length(min=3, max=80),
            validate.Regexp(
                r"^[a-zA-Z0-9_]+$", error="Username must contain only letters, numbers, and underscores."
            ),
        ],
    )
    email = fields.Email(required=True, validate=validate.Length(max=120))
    password = fields.Str(
        required=True,
        validate=validate.Length(min=8, max=128),
    )


class LoginSchema(Schema):
    username = fields.Str(required=True)
    password = fields.Str(required=True)


class ItemCreateSchema(Schema):
    name = fields.Str(required=True, validate=validate.Length(min=1, max=200))
    description = fields.Str(load_default=None, validate=validate.Length(max=5000))
    price = fields.Float(load_default=None, validate=validate.Range(min=0))

    @validates_schema
    def validate_price_precision(self, data, **kwargs):
        if data.get("price") is not None:
            data["price"] = round(data["price"], 2)


class ItemUpdateSchema(Schema):
    name = fields.Str(validate=validate.Length(min=1, max=200))
    description = fields.Str(validate=validate.Length(max=5000))
    price = fields.Float(validate=validate.Range(min=0))

    @validates_schema
    def validate_price_precision(self, data, **kwargs):
        if data.get("price") is not None:
            data["price"] = round(data["price"], 2)


class PaginationSchema(Schema):
    page = fields.Int(load_default=1, validate=validate.Range(min=1))
    per_page = fields.Int(load_default=20, validate=validate.Range(min=1, max=100))

from flask import jsonify
from marshmallow import ValidationError
from werkzeug.exceptions import HTTPException, default_exceptions


def register_error_handlers(app):

    @app.errorhandler(400)
    def bad_request(error):
        return jsonify({"error": "Bad Request", "message": str(error)}), 400

    @app.errorhandler(401)
    def unauthorized(error):
        return (
            jsonify(
                {
                    "error": "Unauthorized",
                    "message": "Authentication is required to access this resource.",
                }
            ),
            401,
        )

    @app.errorhandler(403)
    def forbidden(error):
        return (
            jsonify(
                {
                    "error": "Forbidden",
                    "message": "You do not have permission to perform this action.",
                }
            ),
            403,
        )

    @app.errorhandler(404)
    def not_found(error):
        return (
            jsonify(
                {"error": "Not Found", "message": "The requested resource was not found."}
            ),
            404,
        )

    @app.errorhandler(405)
    def method_not_allowed(error):
        return (
            jsonify(
                {
                    "error": "Method Not Allowed",
                    "message": "The HTTP method is not allowed for this endpoint.",
                }
            ),
            405,
        )

    @app.errorhandler(429)
    def ratelimit_exceeded(error):
        return (
            jsonify(
                {
                    "error": "Too Many Requests",
                    "message": "Rate limit exceeded. Please try again later.",
                    "retry_after": error.description if error.description else None,
                }
            ),
            429,
        )

    @app.errorhandler(500)
    def internal_server_error(error):
        return (
            jsonify(
                {
                    "error": "Internal Server Error",
                    "message": "An unexpected error occurred.",
                }
            ),
            500,
        )

    @app.errorhandler(ValidationError)
    def handle_validation_error(error):
        return (
            jsonify(
                {
                    "error": "Validation Error",
                    "messages": error.messages,
                }
            ),
            422,
        )

    @app.errorhandler(Exception)
    def handle_unhandled(error):
        if isinstance(error, HTTPException):
            return (
                jsonify(
                    {"error": error.name, "message": error.description}
                ),
                error.code,
            )
        return (
            jsonify(
                {
                    "error": "Internal Server Error",
                    "message": "An unexpected error occurred.",
                }
            ),
            500,
        )

