from app import db, limiter
from app.models import User
from app.validators import RegisterSchema, LoginSchema

bp = Blueprint("auth", __name__)


@bp.route("/register", methods=["POST"])
def register():
    schema = RegisterSchema()
    try:
        data = schema.load(request.get_json(silent=True) or {})
    except ValidationError as err:
        return jsonify({"error": "Validation Error", "messages": err.messages}), 422

    if User.query.filter_by(username=data["username"]).first():
        return jsonify({"error": "Conflict", "message": "Username already exists."}), 409

    if User.query.filter_by(email=data["email"]).first():
        return jsonify({"error": "Conflict", "message": "Email already exists."}), 409

    user = User(username=data["username"], email=data["email"])
    user.set_password(data["password"])
    db.session.add(user)
    db.session.commit()

    return jsonify({"message": "User registered successfully.", "user": user.to_dict()}), 201


@bp.route("/login", methods=["POST"])
@limiter.limit("10 per minute")
def login():
    schema = LoginSchema()
    try:
        data = schema.load(request.get_json(silent=True) or {})
    except ValidationError as err:
        return jsonify({"error": "Validation Error", "messages": err.messages}), 422

    user = User.query.filter_by(username=data["username"]).first()
    if user is None or not user.check_password(data["password"]):
        return jsonify({"error": "Unauthorized", "message": "Invalid username or password."}), 401

    access_token = create_access_token(
        identity=str(user.id),
        additional_claims={"username": user.username, "role": user.role},
    )
    refresh_token = create_refresh_token(
        identity=str(user.id),
        additional_claims={"username": user.username, "role": user.role},
    )

    import flask

    flask.g.user_id = user.id
    flask.g.username = user.username

    return jsonify({
        "access_token": access_token,
        "refresh_token": refresh_token,
        "token_type": "bearer",
        "user": user.to_dict(),
    }), 200


@bp.route("/refresh", methods=["POST"])
@jwt_required(refresh=True)
def refresh():
    identity = get_jwt_identity()
    claims = get_jwt()
    access_token = create_access_token(
        identity=identity,
        additional_claims={"username": claims.get("username"), "role": claims.get("role")},
    )
    return jsonify({"access_token": access_token, "token_type": "bearer"}), 200


